### Final Code:
```rust
use clap::Parser;
use serde::{Deserialize, Serialize};
use std::fs;
use std::path::Path;

#[derive(Parser)]
#[command(name = "task_cli")]
#[command(about = "A simple task management CLI", long_about = None)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Parser)]
enum Commands {
    Add {
        #[arg(short, long)]
        task: String,
    },
    List,
    Complete {
        #[arg(short, long)]
        index: usize,
    },
}

#[derive(Serialize, Deserialize, Debug)]
struct Task {
    description: String,
    completed: bool,
}

fn load_tasks(path: &Path) -> Vec<Task> {
    if path.exists() {
        let data = fs::read_to_string(path).expect("Failed to read tasks.json");
        serde_json::from_str(&data).expect("Failed to parse tasks.json")
    } else {
        Vec::new()
    }
}

fn save_tasks(tasks: &Vec<Task>, path: &Path) {
    let data = serde_json::to_string(tasks).expect("Failed to serialize tasks");
    fs::write(path, data).expect("Failed to write tasks.json");
}

fn main() {
    let cli = Cli::parse();
    let path = Path::new("tasks.json");
    let mut tasks = load_tasks(path);

    match cli.command {
        Commands::Add { task } => {
            tasks.push(Task {
                description: task.clone(),
                completed: false,
            });
            save_tasks(&tasks, path);
            println!("Task added: {}", task);
        }
        Commands::List => {
            if tasks.is_empty() {
                println!("No tasks found.");
            } else {
                for (index, task) in tasks.iter().enumerate() {
                    let status = if task.completed { "[X]" } else { "[ ]" };
                    println!("{}: {} - {}", index, status, task.description);
                }
            }
        }
        Commands::Complete { index } => {
            if index < tasks.len() {
                tasks[index].completed = true;
                save_tasks(&tasks, path);
                println!("Task completed: {}", tasks[index].description);
            } else {
                println!("Invalid task index.");
            }
        }
    }
}
```

